fix(anthropic): preserve empty-stream rejection for interrupted responses (#23816)

## Background

#23814 synthesized an Anthropic finish chunk even when a stream ended
before producing output, resolving with empty text and `interrupted`
instead of rejecting with `NoOutputGeneratedError`.

## Summary

- Restore the original completion handler and emit the `interrupted`
fallback only after actual output, preserving empty-stream rejection and
existing error paths.
- Preserve prior usage/metadata and completed finish reasons; cover
empty, partial, and later-message cutoffs and clarify the docs.
- Partial cutoffs still emit a provider finish, so existing interrupted
callbacks and continuation behavior apply.

## End-to-End Verification

verified by running `node --import tsx --input-type=module < repro.ts`
from `examples/ai-functions` after building the packages. Replaying both
recorded fixtures at every event boundary produced **8 no-output
rejections, 26 interrupted partial results, and 2 normal completions**.
A separate comparison against the pre-PR provider confirmed preserved
output, usage, metadata, and error behavior.

Also passed: 720 Anthropic tests in Node and Edge, `pnpm
type-check:full`, and lint/format checks.

<details>

```repro.ts
import { readFileSync } from 'node:fs';
import { createAnthropic } from '@ai-sdk/anthropic';
import { streamText } from 'ai';

for (const file of [
  'anthropic-text.chunks.txt',
  'anthropic-clear-thinking.1.chunks.txt',
]) {
  const events = readFileSync(
    `../../packages/anthropic/src/__fixtures__/${file}`,
    'utf8',
  ).trim().split('\n');

  for (let cutoff = 0; cutoff <= events.length; cutoff++) {
    const anthropic = createAnthropic({
      apiKey: 'mock-key',
      fetch: async () => new Response(
        events.slice(0, cutoff).map(event => `data: ${event}\n\n`).join(''),
        { headers: { 'content-type': 'text/event-stream' } },
      ),
    });
    const result = streamText({
      model: anthropic('claude-sonnet-4-5'),
      prompt: 'Hello',
      maxRetries: 0,
      onError: () => {},
    });

    try {
      console.log(file, cutoff, {
        text: await result.text,
        reasoning: await result.reasoningText,
        finishReason: await result.finishReason,
      });
    } catch (error) {
      console.log(file, cutoff, error.name);
    }
  }
}
```

</details>

fix(ai): add experimental single-consumer streaming to reduce memory retention (#22528)

## Background

#16753

the SDK kept the generated text even after your app had read it. problem
was that reading chunks from textStream didn’t mean the SDK released
those chunks and streamText kept data in several places, leading to
higher memory retention

## Summary

Adds `experimental_lowMemory` option to `streamText`

the option uses the existing execution engine while disabling stream
replay and final-content getters such as text and steps. For plain text
streaming, it also avoids accumulating the complete generated text.
Completion metadata, including usage and finish reason, remains
available.

## End-to-End Verification

verified by running the repro: 
<details>

```ts
import type { LanguageModelV4StreamPart } from '@ai-sdk/provider';
import {
  experimental_streamTextSingleConsumer as streamTextWithMinimalRetention,
  streamText,
} from 'ai';
import { MockLanguageModelV4 } from 'ai/test';
import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { setImmediate } from 'node:timers/promises';
import { run } from '../../lib/run';

//   pnpm --filter ai... build
//   cd examples/ai-functions
//   node --expose-gc --import tsx src/stream-text/mock/text-stream-retention.ts provider
//   node --expose-gc --import tsx src/stream-text/mock/text-stream-retention.ts sdk
//   node --expose-gc --import tsx src/stream-text/mock/text-stream-retention.ts streaming
const mib = 1024 * 1024;
const chunkBytes = 16 * 1024;
const sampleEveryBytes = 16 * mib;

run(async () => {
  const mode = process.argv[2] ?? 'sdk';
  const outputMiB = Number(process.argv[3] ?? 64);
  assert.ok(
    mode === 'sdk' || mode === 'provider' || mode === 'streaming',
    'Use sdk, provider, or streaming mode.',
  );
  assert.ok(
    Number.isSafeInteger(outputMiB) && outputMiB > 0,
    'Output MiB must be a positive integer.',
  );
  assert.ok(globalThis.gc, 'Run node with --expose-gc.');

  const totalBytes = outputMiB * mib;
  const samples: Array<{
    phase: string;
    consumedMiB: number;
    heapUsedMiB: number;
    heapGrowthMiB: number;
  }> = [];
  let baseline: number | undefined;

  async function sample(phase: string, consumedBytes: number) {
    // Let completed stream operations release their temporary references.
    await setImmediate();
    globalThis.gc!();
    const heap = process.memoryUsage().heapUsed;
    baseline ??= heap;
    const row = {
      phase,
      consumedMiB: consumedBytes / mib,
      heapUsedMiB: Number((heap / mib).toFixed(2)),
      heapGrowthMiB: Number(((heap - baseline) / mib).toFixed(2)),
    };
    samples.push(row);
    console.log(row);
  }

  const model = new MockLanguageModelV4({
    doStream: async () => {
      let emittedBytes = 0;
      return {
        stream: new ReadableStream<LanguageModelV4StreamPart>({
          start(controller) {
            controller.enqueue({ type: 'stream-start', warnings: [] });
            controller.enqueue({ type: 'text-start', id: 'text-1' });
          },
          pull(controller) {
            if (emittedBytes < totalBytes) {
              // Create an independent, flat ASCII string on demand. Reusing one
              // string or preallocating an array would distort the comparison.
              const delta = randomBytes(chunkBytes / 2).toString('hex');
              emittedBytes += delta.length;
              controller.enqueue({ type: 'text-delta', id: 'text-1', delta });
              return;
            }

            controller.enqueue({ type: 'text-end', id: 'text-1' });
            controller.enqueue({
              type: 'finish',
              finishReason: { unified: 'stop', raw: 'stop' },
              usage: {
                inputTokens: {
                  total: 0,
                  noCache: 0,
                  cacheRead: undefined,
                  cacheWrite: undefined,
                },
                outputTokens: {
                  total: undefined,
                  text: undefined,
                  reasoning: undefined,
                },
              },
            });
            controller.close();
          },
        }),
      };
    },
  });

  async function consume() {
    let consumedBytes = 0;
    let nextSample = sampleEveryBytes;
    async function count(text: string) {
      consumedBytes += text.length; // ASCII: one character = one byte.
      if (consumedBytes >= nextSample) {
        await sample('streaming', consumedBytes);
        nextSample += sampleEveryBytes;
      }
    }

    if (mode === 'provider') {
      const { stream } = await model.doStream({
        prompt: [
          { role: 'user', content: [{ type: 'text', text: 'Stream.' }] },
        ],
      });
      const reader = stream.getReader();
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (value.type === 'text-delta') await count(value.delta);
        }
      } finally {
        reader.releaseLock();
      }
      await sample('completed', consumedBytes);
    } else if (mode === 'streaming') {
      const result = streamTextWithMinimalRetention({
        model,
        prompt: 'Stream.',
      });
      const stream = result.textStream;
      for await (const delta of stream) {
        await count(delta);
      }
      await sample('completed (stream still live)', consumedBytes);
      assert.equal(await result.finishReason, 'stop');
    } else {
      const result = streamText({ model, prompt: 'Stream.' });
      for await (const delta of result.textStream) {
        await count(delta);
      }
      await sample('completed (result still live)', consumedBytes);

      // Only AFTER measuring the original single-consumer workload, show that
      // all text is still replayable without another provider call. This also
      // keeps result reachable across the preceding GC measurement.
      let replayedBytes = 0;
      for await (const delta of result.textStream) {
        replayedBytes += delta.length;
      }
      assert.equal(replayedBytes, totalBytes);
      console.log(`Replayed ${replayedBytes / mib} MiB without regenerating.`);
    }
    assert.equal(consumedBytes, totalBytes);
    assert.equal(model.doStreamCalls.length, 1);
  }

  console.log(
    `Mode: ${mode}; output: ${outputMiB} MiB; Node: ${process.version}`,
  );
  await sample('baseline', 0);
  await consume();
  await sample('result released', totalBytes);
  console.table(samples);
});
```
</details>

